import { useNode } from "../runtime/store.js";

/** Flex container shared by pages, cards, forms, headers, navbars and plain containers. */
export default function Stack({ id, type, as: Tag = "div", layout = {}, style, children, onSubmit }) {
  const { attrs } = useNode(id, type);
  const { direction = "column", gap = 12, align = "stretch", justify = "start" } = layout;
  const className = `ng-${type} ng-stack ng-stack--${direction} ng-align-${align} ng-justify-${justify}`;
  const handleSubmit = onSubmit
    ? (event) => {
        event.preventDefault();
        onSubmit(event);
      }
    : (event) => event.preventDefault();

  return (
    <Tag {...attrs} className={className} style={{ gap, ...style }} onSubmit={Tag === "form" ? handleSubmit : undefined}>
      {children}
    </Tag>
  );
}

