function ContactPage() {
  const ui = useUI();
  const handleLnkBackClick = () => runActions("lnk_back", LNK_BACK_CLICK, ui);

  return (
    <Page id="page_contact" layout={{ gap: 16 }}>
      <Heading id="h_contact" label="Contact" level={1} />
